{
  "instrument": "Regulation (EU) 2023/1115 — Shopify blog",
  "jurisdiction": "EU",
  "summary": "Collect due diligence statements from your suppliers and the plot geolocation of the raw material if you sell wood, leather, coffee, cocoa, rubber, soy or palm-oil products in the EU. This Shopify blog post summarises the EU Deforestation Regulation for ecommerce merchants.",
  "effective_dates": [],
  "obligations": [
    {
      "text": "Obtain supplier due diligence statements and plot geolocation for covered products.",
      "quote": "If you place these products on the EU market you need due diligence statements from your suppliers and the geolocation of the plots where the raw material was grown."
    }
  ]
}
